<?php require __DIR__ . '/../config/bootstrap.php'; require_admin(); $saved=false; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf(); $fields=['organization_name','tagline','about_text','hero_title','hero_subtitle','phone','email','address','footer_text']; foreach($fields as $key){$stmt=$pdo->prepare('INSERT INTO settings(setting_key,setting_value_mr,setting_value_en,group_name) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE setting_value_mr=VALUES(setting_value_mr), setting_value_en=VALUES(setting_value_en)'); $group=in_array($key,['phone','email','address'],true)?'contact':(in_array($key,['hero_title','hero_subtitle'],true)?'homepage':($key==='footer_text'?'footer':'organization')); $stmt->execute([$key,trim($_POST[$key.'_mr']??''),trim($_POST[$key.'_en']??''),$group]);} audit($pdo,'updated','settings'); $saved=true;} function field_value(PDO $pdo,string $key,string $lang):string{return setting($pdo,$key,$lang);} require __DIR__ . '/_layout.php'; admin_header('संस्था सेटिंग्ज'); ?>
<div class="admin-title"><h1 data-testid="settings-title">संस्था सेटिंग्ज</h1><p data-testid="settings-subtitle">साइटवरील माहिती कोड न बदलता व्यवस्थापित करा.</p></div><?php if($saved): ?><div class="notice" data-testid="settings-success">सेटिंग्ज यशस्वीरित्या जतन केल्या.</div><?php endif; ?><section class="panel"><h2>मूलभूत ओळख</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="setting-form"><?php $labels=['organization_name'=>'संस्थेचे नाव','tagline'=>'ब्रीदवाक्य','about_text'=>'आमच्याविषयी','hero_title'=>'मुख्य शीर्षक','hero_subtitle'=>'मुख्य उपशीर्षक','phone'=>'मोबाइल','email'=>'ईमेल','address'=>'पत्ता','footer_text'=>'फूटर मजकूर']; foreach($labels as $key=>$label): $isLong=in_array($key,['about_text','hero_subtitle','address','footer_text'],true); ?><div class="field <?= $isLong?'full':'' ?>"><label><?=e($label)?></label><?php if($isLong): ?><textarea name="<?=e($key)?>_mr" data-testid="settings-<?=e($key)?>-mr-input"><?=e(field_value($pdo,$key,'mr'))?></textarea><?php else: ?><input name="<?=e($key)?>_mr" value="<?=e(field_value($pdo,$key,'mr'))?>" data-testid="settings-<?=e($key)?>-mr-input"><?php endif; ?><small style="color:var(--muted)">मराठी</small><?php if($isLong): ?><textarea name="<?=e($key)?>_en" placeholder="English (optional)" data-testid="settings-<?=e($key)?>-en-input"><?=e(field_value($pdo,$key,'en'))?></textarea><?php else: ?><input name="<?=e($key)?>_en" placeholder="English (optional)" value="<?=e(field_value($pdo,$key,'en'))?>" data-testid="settings-<?=e($key)?>-en-input"><?php endif; ?></div><?php endforeach; ?></div><div class="form-actions"><button class="btn btn-gold" type="submit" data-testid="settings-save-button">सेटिंग्ज जतन करा</button></div></form></section><?php admin_footer(); ?>